style.css:
@-moz-document domain("neoseeker.com") {
/* ============================================================
     Neoseeker Dark
     Neoseeker runs a classic Bootstrap-2-era frontend with
     HARDCODED colors (no CSS custom-property system) shared across
     www (home, game hubs, walkthroughs/guides/cheats/FAQs, search,
     forums) and the MediaWiki subdomains (pokemon./pes./neowiki.).
     We re-skin per-element on stable id/class names: a near-black
     base, elevated card surfaces, softened borders, a refined
     Neoseeker blue, and remapped status alerts. Text is forced
     light everywhere to kill dark-on-dark on the hardcoded greys.
     ============================================================ */

  :root {
    color-scheme: dark;
    --neo-base: #14181d;
    --neo-elev: #1c2128;
    --neo-elev2: #232a33;
    --neo-head: #0d1117;
    --neo-border: #2a313a;
    --neo-text: #e6edf3;
    --neo-text-2: #c4cdd6;
    --neo-muted: #9aa4af;
    --neo-link: #5fb0e6;
    --neo-link-hover: #9bd4ff;
    --neo-blue: #2f6c93;
  }

  /* ---- Base ------------------------------------------------- */
  html,
  body,
  body#application,
  #application {
    background-color: var(--neo-base) !important;
    color: var(--neo-text-2) !important;
  }

  #container,
  #maincolumn,
  #main,
  #content,
  #page_body,
  #bodyContent,
  #mw-content-text {
    background-color: var(--neo-base) !important;
    color: var(--neo-text-2) !important;
  }

  #maincolumn {
    border-left-color: var(--neo-border) !important;
    border-right-color: var(--neo-border) !important;
  }

  /* Soften every stray light border into a subtle dark line */
  * {
    border-color: var(--neo-border) !important;
  }

  /* ---- Typography ------------------------------------------- */
  h1,
  h2,
  h3,
  h4,
  h5,
  h6,
  legend,
  caption,
  b,
  strong,
  dt {
    color: var(--neo-text) !important;
  }

  p,
  li,
  td,
  th,
  dd,
  span,
  small,
  label,
  figcaption,
  blockquote {
    color: var(--neo-text-2) !important;
  }

  .muted,
  .text-muted,
  .smaller,
  .smaller-xs,
  .text-small,
  .text-light,
  .date,
  .timestamp,
  .meta,
  .byline,
  time,
  .who_liked,
  .text-secondary {
    color: var(--neo-muted) !important;
  }

  /* News article tagline/subtitle (`#news_description.news_tagline`) is a
     <div> the site colors a hardcoded dark purple #443344 — reads dark-on-
     dark here (the generic p/span text rule doesn't reach a bare div). */
  #news_description,
  .news_tagline {
    color: var(--neo-text-2) !important;
  }

  /* ---- Links / accent --------------------------------------- */
  a,
  a:link,
  a:visited {
    color: var(--neo-link) !important;
  }

  a:hover,
  a:focus {
    color: var(--neo-link-hover) !important;
  }

  /* "new / missing page" red links (wiki + guide TOC): lift off dark.
     Placed AFTER the generic link rule so it wins on source order;
     extra specificity to beat the site's own colored .new rule. */
  a.new,
  a.new:link,
  a.new:visited,
  a.accordion-toggle.new,
  .accordion a.new,
  .section-list a.new,
  #mw-content-text a.new,
  .new > a {
    color: #f08b80 !important;
  }

  /* Guide wiki-nav sidebar TOC "new/missing page" links: the site ships
     `body.desktop #wiki-navigation a.new` (a dark brick-red that reads
     dark-on-dark here). Beat it with a two-ID selector. */
  #right_content #wiki-navigation a.new,
  #right_content #wiki-navigation a.new:link,
  #right_content #wiki-navigation a.new:visited,
  #wiki-sidebar #wiki-navigation a.new {
    color: #f08b80 !important;
  }

  /* keep heading links and breadcrumb readable */
  h1 a,
  h2 a,
  h3 a {
    color: var(--neo-link) !important;
  }

  /* ---- Header / nav bars ------------------------------------ */
  #header-navbar,
  #header-navbar .navbar,
  #header,
  #topbar {
    background-color: var(--neo-head) !important;
    background-image: none !important;
  }

  #header-navbar .navbar-inner,
  .navbar-inner {
    background-color: var(--neo-blue) !important;
    background-image: none !important;
    border-color: var(--neo-border) !important;
    box-shadow: none !important;
  }

  .navbar-inner,
  .navbar-inner a,
  .navbar .nav > li > a,
  .navbar-inner .brand {
    color: #eaf2f8 !important;
  }

  .navbar .nav > li > a:hover,
  .navbar .nav > li.active > a {
    background-color: rgba(0, 0, 0, 0.25) !important;
    color: #ffffff !important;
  }

  #memberbar,
  #memberbar .navbar-inner {
    background-color: var(--neo-head) !important;
    background-image: none !important;
    border-color: var(--neo-border) !important;
  }

  #memberbar,
  #memberbar a,
  #memberbar .nav > li > a {
    color: var(--neo-text-2) !important;
  }

  /* ---- Cards / sections / panels ---------------------------- */
  .section-list,
  .section-form,
  .section-box,
  .section,
  .section-spaced,
  .well,
  .panel,
  .box,
  .module,
  .widget,
  .dropdown-menu,
  .popover,
  .tooltip-inner,
  .modal,
  .modal-body,
  .modal-header,
  .modal-footer,
  .forum-group,
  .community-box,
  #right_content > div,
  #left_content > div,
  #sidebar,
  .sidebar {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    box-shadow: none !important;
  }

  /* sub-headers / table-ish header strips */
  .section-header,
  .section-footer,
  .heading,
  .nav-header,
  .panel-heading,
  .box-header,
  thead th,
  .table-list th,
  #nav_prev_next,
  .status_msg,
  .status_msg.section,
  #spotlight_forums,
  #forum-user-platform-bar {
    background-color: var(--neo-elev2) !important;
    background-image: none !important;
    color: var(--neo-text) !important;
    border-color: var(--neo-border) !important;
  }

  .section-header,
  .section-header a,
  .heading,
  .heading a,
  #spotlight_forums,
  #spotlight_forums a,
  #forum-user-platform-bar,
  #forum-user-platform-bar a {
    color: var(--neo-text) !important;
  }

  /* the already-dark inverse panel: harmonize tone + lift text */
  .section-info-inverse {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
  }

  .section-info-inverse,
  .section-info-inverse * {
    color: var(--neo-text-2) !important;
  }

  .section-info-inverse .section-header {
    background-color: var(--neo-elev2) !important;
    color: var(--neo-text) !important;
  }

  /* ---- Tables ----------------------------------------------- */
  table,
  .table,
  .table-list,
  .MainPageBG {
    background-color: transparent !important;
    border-color: var(--neo-border) !important;
  }

  td,
  th {
    border-color: var(--neo-border) !important;
  }

  .table-list tbody > tr > td,
  .table-list tbody > tr > th,
  .table-list-bordered tbody > tr > td,
  .table-list-bordered tbody > tr > th,
  .table-list-wide-column tbody > tr > td,
  .table-list-wide-column tbody > tr > th,
  td.row,
  td.forum,
  tr.row td,
  .table-striped tbody > tr:nth-child(odd) > td,
  .table-striped tbody > tr:nth-child(odd) > th {
    background-color: var(--neo-elev) !important;
  }

  .table-striped tbody > tr:nth-child(even) > td,
  .table-striped tbody > tr:nth-child(even) > th,
  .table-list tbody > tr:nth-child(2n + 1) > td,
  .table-list tbody > tr:nth-child(2n + 1) > th,
  .table-list-bordered tbody > tr:nth-child(2n + 1) > td,
  .table-list-bordered tbody > tr:nth-child(2n + 1) > th,
  .table-list-wide-column tbody > tr:nth-child(2n + 1) > td,
  .table-list-wide-column tbody > tr:nth-child(2n + 1) > th {
    background-color: var(--neo-elev2) !important;
  }

  table tr:hover > td,
  .table-hover tbody > tr:hover > td {
    background-color: #2b333d !important;
  }

  /* Forum index / thread-list tables stripe their COLUMNS via
     `<col class="norm|alt">` (light #eef0f9 / #c6d0e7) painted behind
     transparent `<td>`s — so the light column bg bleeds through as washed
     light-on-light rows the row/cell selectors never touch. Darken the
     columns to the elevated surfaces so the forum/thread text reads. */
  #forumlist col.norm,
  #threadlist col.norm,
  .table-list col.norm,
  col.norm {
    background-color: var(--neo-elev) !important;
  }

  #forumlist col.alt,
  #threadlist col.alt,
  .table-list col.alt,
  col.alt {
    background-color: var(--neo-elev2) !important;
  }

  /* Some forum rows ALSO carry their own `<td class="norm|alt">` (the
     post-count / last-reply columns) whose light bg paints ON TOP of the
     darkened <col>, masking the col fix. Darken those cells to match. */
  #forumlist td.norm,
  #threadlist td.norm,
  .table-list td.norm {
    background-color: var(--neo-elev) !important;
  }

  #forumlist td.alt,
  #threadlist td.alt,
  .table-list td.alt {
    background-color: var(--neo-elev2) !important;
  }

  /* Forum thread type-tag pills: `news` / `announcement` ship a light
     #d4def7 chip that reads light-on-light. Darken to an elevated chip and
     keep the accent-blue label. (The purple `.tag-gaming` chip is fine.) */
  a.label.tag-news,
  a.label.tag-announcement,
  .label.tag-news,
  .label.tag-announcement {
    background-color: var(--neo-elev2) !important;
    color: var(--neo-link) !important;
  }

  /* Hardware-review spec tables (`table.mwt`) paint their label column a
     light #dbe5f1 via a site class (no inline style) while the value column
     is transparent — so the labels wash out light-on-light. Darken the
     cells to elevated surfaces, keeping the label column a touch lighter so
     the two-tone spec-table layout is preserved. */
  table.mwt td,
  table.mwt th {
    background-color: var(--neo-elev) !important;
    color: var(--neo-text-2) !important;
  }

  table.mwt td:first-child,
  table.mwt th:first-child {
    background-color: var(--neo-elev2) !important;
    color: var(--neo-text) !important;
  }

  /* ---- Alerts / callouts (recolored, semantics kept) -------- */
  .alert,
  .alert-info,
  .alert-primary {
    background-color: #14323f !important;
    border-color: #2f6c93 !important;
    color: #cfe6f5 !important;
  }

  .alert-success {
    background-color: #16301c !important;
    border-color: #2c6b3a !important;
    color: #b9e6c4 !important;
  }

  .alert-warning {
    background-color: #3a2f12 !important;
    border-color: #8a6d1f !important;
    color: #f0dca0 !important;
  }

  .alert-danger,
  .alert-error {
    background-color: #3a1d1f !important;
    border-color: #8c3b3f !important;
    color: #f3c2c4 !important;
  }

  .alert *,
  .alert a {
    color: inherit !important;
  }

  .label,
  .badge {
    color: #ffffff !important;
  }

  /* progress / in-progress markers */
  .progress,
  .in_progress {
    background-color: var(--neo-elev2) !important;
  }

  /* progress-bar fill keeps its accent; force dark text on it for contrast */
  .progress .bar,
  .bar {
    color: #14181d !important;
    text-shadow: none !important;
  }

  /* "Support Us" yellow pill / floating donation widget: dark text
     on its bright yellow bg. High-specificity to beat the link rule. */
  a.btn-support,
  a.btn-support:link,
  a.btn-support:visited,
  a.btn-support:hover,
  a.btn-support *,
  body a.btn-support,
  body .btn-support a {
    color: #14181d !important;
  }

  /* guide TOC "you are here" item ships a bright yellow bg with blue
     link text (fails on dark). Recolor to the accent blue + light text.
     The wiki-navigation guide sidebar highlights the current chapter on the
     `<li class="active">` CONTAINER (not the anchor), and forces its label
     dark via -webkit-text-fill-color — so target the container itself and
     pin BOTH color and fill-color light, or the bright #ffd500 bar leaks. */
  .section-spaced-small.active,
  .toc-item.active,
  li.active > a,
  #wiki-navigation li.active,
  .section-list li.active {
    background-color: var(--neo-blue) !important;
    color: #ffffff !important;
  }

  .section-spaced-small.active a,
  .section-spaced-small.active a:link,
  .section-spaced-small.active a:visited,
  .section-spaced-small.active *,
  #wiki-navigation li.active,
  #wiki-navigation li.active a,
  #wiki-navigation li.active a:link,
  #wiki-navigation li.active a:visited,
  #wiki-navigation li.active .bullet,
  #wiki-navigation li.active * {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* prev/next pagination arrows: keep text light on dark. The forum
     pagination ships its own .pagenav_nextprev a.next/.prev rule (greyish
     #625e51 that reads dark-on-dark here), so match its specificity. */
  a.next,
  a.prev,
  a.next *,
  a.prev *,
  #nav_prev_next a,
  #nav_prev_next a *,
  .pagenav_nextprev a,
  .pagenav_nextprev a.next,
  .pagenav_nextprev a.prev,
  .pagination .pagenav_nextprev a,
  .pagenav_pages a,
  .pagination-spaced a,
  .pagination .pagenav_pages a {
    color: var(--neo-text-2) !important;
  }

  /* ---- Forms / inputs / search ------------------------------ */
  input,
  textarea,
  select,
  .input-full,
  .form-control,
  #neo-search,
  #searchInput,
  .uneditable-input {
    background-color: #0f141a !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text) !important;
    box-shadow: none !important;
  }

  input:focus,
  textarea:focus,
  select:focus,
  .form-control:focus {
    border-color: var(--neo-link) !important;
    box-shadow: 0 0 0 2px rgba(95, 176, 230, 0.25) !important;
  }

  ::placeholder {
    color: var(--neo-muted) !important;
    opacity: 1 !important;
  }

  :-ms-input-placeholder {
    color: var(--neo-muted) !important;
  }

  /* ---- Buttons ---------------------------------------------- */
  .btn,
  button,
  input[type="submit"],
  input[type="button"],
  .input-group-addon {
    background-color: var(--neo-elev2) !important;
    background-image: none !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text) !important;
    box-shadow: none !important;
    text-shadow: none !important;
  }

  .btn:hover,
  button:hover,
  input[type="submit"]:hover,
  input[type="button"]:hover {
    background-color: #2e3742 !important;
    color: #ffffff !important;
  }

  .btn-primary,
  .btn-info,
  a.btn-primary,
  a.btn-primary:link,
  a.btn-primary:visited,
  a.btn-info,
  .btn-primary *,
  .btn-info * {
    background-color: var(--neo-blue) !important;
    border-color: #265572 !important;
    color: #ffffff !important;
  }

  .btn-primary *,
  .btn-info *,
  .btn-success *,
  .btn-danger * {
    background-color: transparent !important;
  }

  .btn-primary:hover,
  .btn-info:hover {
    background-color: #387ba6 !important;
  }

  .btn-success {
    background-color: #2c6b3a !important;
    border-color: #2c6b3a !important;
    color: #ffffff !important;
  }

  .btn-danger {
    background-color: #8c3b3f !important;
    border-color: #8c3b3f !important;
    color: #ffffff !important;
  }

  /* ---- Code / preformatted ---------------------------------- */
  pre,
  code,
  kbd,
  samp,
  tt {
    background-color: #0d1117 !important;
    border-color: var(--neo-border) !important;
    color: #c9d1d9 !important;
  }

  /* ---- Dropdowns / menus / floating surfaces ---------------- */
  .dropdown-menu {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.5) !important;
  }

  .dropdown-menu > li > a,
  .dropdown-menu li a {
    color: var(--neo-text-2) !important;
  }

  .dropdown-menu > li > a:hover,
  .dropdown-menu > li > a:focus,
  .dropdown-menu > .active > a {
    background-color: var(--neo-blue) !important;
    background-image: none !important;
    color: #ffffff !important;
  }

  /* ---- Tabs / pills / pagination ---------------------------- */
  .nav-tabs > li > a,
  .nav-pills > li > a,
  .pagination a,
  .pagination span,
  .tabs a {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  .nav-tabs > li.active > a,
  .nav-tabs > li > a:hover,
  .nav-pills > li.active > a,
  .pagination .active a,
  .pagination .active span,
  .pagination a:hover {
    background-color: var(--neo-blue) !important;
    border-color: var(--neo-border) !important;
    color: #ffffff !important;
  }

  /* breadcrumbs */
  .breadcrumb,
  #breadcrumb,
  .breadcrumbs {
    background-color: transparent !important;
  }

  /* ---- Forum specifics -------------------------------------- */
  .neoforums #content {
    background-color: var(--neo-base) !important;
  }

  /* white header/clearfix wrappers that sit on the forum body */
  .neoforums .clearfix,
  #entireheader,
  #footerbottom {
    background-color: var(--neo-base) !important;
    color: var(--neo-text-2) !important;
  }

  #footerbottom h5,
  #footerbottom li,
  #footerbottom a {
    color: var(--neo-text-2) !important;
  }

  /* bottom server/info bar (Neoseeker blue strip): lift its text */
  footerbar,
  #footerbar,
  .footerbar {
    background-color: var(--neo-head) !important;
    color: var(--neo-muted) !important;
  }

  footerbar a,
  footerbar span,
  #footerbar a,
  #footerbar span {
    color: var(--neo-text-2) !important;
  }

  .post,
  .message,
  .postbody,
  .forum-post,
  .comment,
  .comment-body,
  #comments_list .heading {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  /* Forum thread posts ship a classic table layout the generic .post
     selectors miss: tr.messagerow rows, the td.authorcol postbit column,
     the td.msgcol body and the .section-vu content view all default to a
     light lavender / white that left light text invisible on light bg. */
  tr.messagerow,
  tr.messagerow.norm,
  tr.norm,
  tr.thread_note,
  td.msgcol,
  div.section-vu,
  div.cookiecrumb {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  tr.messagerow.alt,
  td.authorcol {
    background-color: var(--neo-elev2) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  blockquote,
  .quote,
  .bbcode_quote,
  div.qt {
    background-color: var(--neo-elev2) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  /* Forum thread "post tags:" strip (div#post_tags.inner.borders) ships a
     light #E0E3EB bar with a light #efefef tag pill — an uncovered light
     strip on the dark thread. Darken the bar to the elevated surface and
     give its tag pill a dark chip with readable link text. */
  #post_tags,
  #post_tags.inner {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  #post_tags .tag,
  #post_tags .label,
  #post_tags a.tag.label {
    background-color: var(--neo-elev2) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-link) !important;
  }

  /* Collapsed blog/activity posts (member profiles) end with a "read more"
     scroll-fade gradient that fades to WHITE, washing the last lines out.
     Remap the fade to the elevated surface so text stays readable. */
  .collapsed-expand {
    background-image: linear-gradient(
      rgba(28, 33, 40, 0) 0%,
      rgba(28, 33, 40, 1) 80%
    ) !important;
  }

  .spoiler,
  .bbcode_spoiler {
    background-color: var(--neo-elev2) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  /* ---- MediaWiki (pokemon./pes./neowiki.) ------------------- */
  .mw-body,
  #mw-content-text,
  .mw-parser-output,
  #toc,
  .toc,
  .toccolours,
  .infobox,
  .navbox,
  .wikitable {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  .wikitable > tr > th,
  .wikitable > * > tr > th,
  .infobox th,
  .navbox-title,
  .toctitle {
    background-color: var(--neo-elev2) !important;
    color: var(--neo-text) !important;
  }

  .wikitable > tr > td,
  .wikitable > * > tr > td,
  .infobox td {
    background-color: var(--neo-elev) !important;
    color: var(--neo-text-2) !important;
  }

  /* Wiki cells/spans that hardcode a SATURATED color bg inline (e.g.
     Pokemon type-colored infobox cells) keep that bg — so force their
     OWN text DARK to stay readable. Self-targeted (plus direct text
     children) so cells we darkened to elevated surfaces aren't touched.
     Skip transparent/none inline bgs (those sit on our dark elevated
     surface and must keep LIGHT text — forcing dark there = invisible). */
  .mw-parser-output td[style*="background"]:not([style*="transparent"]):not([style*="background:none"]):not([style*="background-color:none"]):not([style*="#e3f6fb"]):not([style*="#cdf1c7"]),
  .mw-parser-output th[style*="background"]:not([style*="transparent"]):not([style*="background:none"]):not([style*="background-color:none"]):not([style*="#e3f6fb"]):not([style*="#cdf1c7"]),
  .mw-parser-output td[style*="background"]:not([style*="transparent"]) > a,
  .mw-parser-output td[style*="background"]:not([style*="transparent"]) > b,
  .mw-parser-output td[style*="background"]:not([style*="transparent"]) > span,
  .mw-parser-output th[style*="background"]:not([style*="transparent"]) > a,
  .mw-parser-output th[style*="background"]:not([style*="transparent"]) > b {
    color: #14181d !important;
  }

  /* Inline-COLORED infobox wrappers — Pokemon "Type Matchups", the main
     species infobox, evolution-chain boxes, move/level/breeding tables —
     are <div>s with a hardcoded light inline `background-color` (pale
     yellow #f8f7c9, peach #FDD4A3, lavender #C0C7FF, green #92E584, orange
     #F7BB75, light-blue #89C0E8, etc.), not cells, so the td/th rule above
     misses them. They keep that light bg, but text sitting DIRECTLY on the
     box bg inherits our LIGHT body text → column headers ("Type", "Attack
     Advantages"…), labels and data rows wash out light-on-light.
       Fix: darken (a) the box's own direct text and (b) any TRANSPARENT
     descendant cell (`td`/`th` with no inline bg of its own) plus its
     inline text children. Cells that carry their OWN inline bg are left to
     the saturated-cell td/th rule above — that deliberately darkens only
     their DIRECT a/b/span children, which keeps LIGHT text on DARK brand
     cells (e.g. the near-black #090909 game-version cells) readable rather
     than painting them dark-on-dark. `<b>`/`<strong>` carry their own
     !important light color, so they must be named explicitly. Scoped to
     .mw-parser-output; EXCLUDE transparent/none bgs and the hexes we remap
     to DARK elevated surfaces below (#a181db/#98e2df/#b782c9/#d2a7e0). */
  .mw-parser-output div[style*="background"]:not([style*="transparent"]):not([style*="background:none"]):not([style*="background-color:none"]):not([style*="#a181db"]):not([style*="#98e2df"]):not([style*="#b782c9"]):not([style*="#d2a7e0"]),
  .mw-parser-output div[style*="background"]:not([style*="transparent"]):not([style*="#a181db"]):not([style*="#98e2df"]):not([style*="#b782c9"]):not([style*="#d2a7e0"]) td:not([style*="background"]),
  .mw-parser-output div[style*="background"]:not([style*="transparent"]):not([style*="#a181db"]):not([style*="#98e2df"]):not([style*="#b782c9"]):not([style*="#d2a7e0"]) td:not([style*="background"]) b,
  .mw-parser-output div[style*="background"]:not([style*="transparent"]):not([style*="#a181db"]):not([style*="#98e2df"]):not([style*="#b782c9"]):not([style*="#d2a7e0"]) td:not([style*="background"]) strong,
  .mw-parser-output div[style*="background"]:not([style*="transparent"]):not([style*="#a181db"]):not([style*="#98e2df"]):not([style*="#b782c9"]):not([style*="#d2a7e0"]) td:not([style*="background"]) a,
  .mw-parser-output div[style*="background"]:not([style*="transparent"]):not([style*="#a181db"]):not([style*="#98e2df"]):not([style*="#b782c9"]):not([style*="#d2a7e0"]) td:not([style*="background"]) span,
  .mw-parser-output div[style*="background"]:not([style*="transparent"]):not([style*="#a181db"]):not([style*="#98e2df"]):not([style*="#b782c9"]):not([style*="#d2a7e0"]) td:not([style*="background"]) small,
  .mw-parser-output div[style*="background"]:not([style*="transparent"]):not([style*="#a181db"]):not([style*="#98e2df"]):not([style*="#b782c9"]):not([style*="#d2a7e0"]) caption,
  .mw-parser-output td[style*="#f8f7c9"] * {
    color: #14181d !important;
  }

  /* Light PASTEL inline surfaces (move tables, section boxes, light
     decorative wrappers) are too bright on dark — darken to elevated and
     keep text light. These hexes are the recurring light pastels Neoseeker
     wikis use; saturated type-color cells above are left untouched. */
  .mw-parser-output td[style*="#e3f6fb"],
  .mw-parser-output th[style*="#e3f6fb"],
  .mw-parser-output td[style*="#cdf1c7"],
  .mw-parser-output th[style*="#cdf1c7"],
  .mw-parser-output div[style*="#a181db"],
  .mw-parser-output div[style*="#98e2df"],
  .mw-parser-output div[style*="#b782c9"],
  .mw-parser-output div[style*="#d2a7e0"] {
    background-color: var(--neo-elev) !important;
    background-image: none !important;
    color: var(--neo-text-2) !important;
  }

  .mw-parser-output td[style*="#e3f6fb"],
  .mw-parser-output td[style*="#e3f6fb"] *,
  .mw-parser-output td[style*="#cdf1c7"],
  .mw-parser-output td[style*="#cdf1c7"] *,
  .mw-parser-output div[style*="#a181db"],
  .mw-parser-output div[style*="#98e2df"],
  .mw-parser-output div[style*="#b782c9"],
  .mw-parser-output div[style*="#d2a7e0"] {
    color: var(--neo-text-2) !important;
  }

  /* NeoWiki (neowiki.) main-page templates hardcode near-white inline
     pastels — a big mintcream #f5fffa content TD plus green #cef2e0 and blue
     #cedff2 section-header cells — which our light body text then washes out
     light-on-light. Darken these specific light pastels to the elevated
     surface and keep ALL their text light. The #mw-content-text ID prefix
     out-specifies the saturated-cell dark-text rule above (which would
     otherwise repaint the TD's own text + direct children dark → dark-on-
     dark); the trailing link rule keeps in-cell links accent-blue. */
  #mw-content-text td[style*="#f5fffa"],
  #mw-content-text th[style*="#f5fffa"],
  #mw-content-text td[style*="#f5faff"],
  #mw-content-text th[style*="#f5faff"],
  #mw-content-text h2[style*="#cef2e0"],
  #mw-content-text td[style*="#cef2e0"],
  #mw-content-text th[style*="#cef2e0"],
  #mw-content-text h2[style*="#cedff2"],
  #mw-content-text td[style*="#cedff2"],
  #mw-content-text th[style*="#cedff2"] {
    background-color: var(--neo-elev) !important;
    background-image: none !important;
    color: var(--neo-text-2) !important;
  }

  #mw-content-text td[style*="#f5fffa"],
  #mw-content-text td[style*="#f5fffa"] *,
  #mw-content-text td[style*="#f5faff"],
  #mw-content-text td[style*="#f5faff"] *,
  #mw-content-text td[style*="#cef2e0"],
  #mw-content-text td[style*="#cef2e0"] *,
  #mw-content-text td[style*="#cedff2"],
  #mw-content-text td[style*="#cedff2"] *,
  #mw-content-text h2[style*="#cef2e0"],
  #mw-content-text h2[style*="#cedff2"] {
    color: var(--neo-text-2) !important;
    -webkit-text-fill-color: var(--neo-text-2) !important;
  }

  #mw-content-text td[style*="#f5fffa"] a,
  #mw-content-text td[style*="#f5faff"] a,
  #mw-content-text td[style*="#cef2e0"] a,
  #mw-content-text td[style*="#cedff2"] a {
    color: var(--neo-link) !important;
    -webkit-text-fill-color: var(--neo-link) !important;
  }

  /* image thumb frames in wiki content (incl. gallery thumbs in the new
     MediaWiki skin: .gallerybox .thumb defaults to a light #f8f9fa via a
     high-specificity skin rule, so descend deep to win) */
  .mw-parser-output .thumb,
  .mw-parser-output .thumbinner,
  div.thumb,
  html body ul.gallery li.gallerybox div.thumb,
  html body ul.gallery li.gallerybox div.thumb div.thumbinner {
    background-color: var(--neo-elev) !important;
    color: var(--neo-text-2) !important;
  }

  /* Bootstrap "polaroid" thumbnail frames (game-hub Media/screenshot
     galleries) default to a white padded border around each thumb. */
  .img-polaroid,
  .thumbnail,
  a.thumbnail,
  .media-thumb {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    box-shadow: none !important;
  }

  /* Guide/FAQ `.section-info` callout boxes (e.g. "BOSS FIGHT: …") ship an
     inline LIGHT background (#d6d8d9 body + #8a8b8c header) with dark text.
     We darken the box + header to elevated surfaces via the `.section*`
     rules, but the MediaWiki `div[style*="background"]` dark-text rule above
     (high specificity from its stacked `:not()`s) then repaints their text
     #14181d → invisible dark-on-dark headers/labels. Re-light the text; the
     `#wiki-content`/`#mw-content-text` ID prefix out-specifies that rule.
     Only `color` is remapped (the site sets no `-webkit-text-fill-color`, so
     fill follows currentColor) — this leaves link/image fill colors intact. */
  #wiki-content .section-info,
  #wiki-content .section-info > center,
  #wiki-content .section-info > b,
  #wiki-content .section-info > strong,
  #mw-content-text .section-info,
  #mw-content-text .section-info > center,
  #mw-content-text .section-info > b,
  #mw-content-text .section-info > strong {
    color: var(--neo-text-2) !important;
  }

  #wiki-content .section-info .section-header,
  #wiki-content .section-info .section-header center,
  #wiki-content .section-info .section-header *,
  #mw-content-text .section-info .section-header,
  #mw-content-text .section-info .section-header center,
  #mw-content-text .section-info .section-header * {
    color: var(--neo-text) !important;
  }

  /* ---- Footer ----------------------------------------------- */
  #footer,
  .footer,
  #debugfooter {
    background-color: var(--neo-head) !important;
    background-image: none !important;
    color: var(--neo-muted) !important;
    border-color: var(--neo-border) !important;
  }

  #footer a,
  .footer a {
    color: var(--neo-link) !important;
  }

  /* ---- Misc: horizontal rules, selection -------------------- */
  hr {
    border-color: var(--neo-border) !important;
    background-color: var(--neo-border) !important;
  }

  ::selection {
    background-color: rgba(95, 176, 230, 0.3);
  }
}
